mapper.select:
select count(*)
from directory_nodes
where user_id = #{userId}
and deleted_at is null
and id in

    #{id}

mapper.update:
with recursive subtree (id) as ( select id from directory_nodes where user_id = #{userId} and deleted_at is null and id = #{id}
union distinct
select child.id from directory_nodes child join subtree parent on child.parent_id = parent.id where child.user_id = #{userId} and child.deleted_at is null ) update directory_nodes node join subtree on subtree.id = node.id set node.deleted_at = current_timestamp(6), node.deleted_root_id = #{id} where node.deleted_at is null

sql.where:
and d.user_id = #{userId}
and d.deleted_at is null


    and d.label like concat('%', #{keyword}, '%')



    and d.node_type = #{nodeType}



    and exists(
        select 1
        from directory_node_tags dnt
        where dnt.directory_node_id = d.id
            and dnt.tag_id in

                #{tagId}

    )



    and d.created_at >= #{startTime}



    and d.created_at < #{endTime}

mapper.select:
select d.id
from directory_nodes d



order by d.created_at desc, d.id desc

limit #{limit}
offset #{offset}

sql.where:
and user_id = #{userId}
and deleted_at is not null
and deleted_root_id = id


    and label like concat('%', #{keyword}, '%')



    and node_type = #{nodeType}



    and deleted_at >= #{startTime}



    and deleted_at < #{endTime}

mapper.select:
select id, label, x, y, node_type, created_at, updated_at, deleted_at
from directory_nodes



order by deleted_at desc, id desc

limit #{limit}
offset #{offset}
